// Keeps focus clear of a bar pinned over one edge of the viewport (WCAG 2.4.11). Anything scrolled
// into view there, a control reached by Tab or a heading jumped to by its anchor, would land behind
// the bar, so the document's scroll padding on that edge is set to how far the bar reaches into the
// viewport; browsers honour it when they scroll an element into view. Shared by the units that pin
// themselves: SiteHeader at the top, BottomNav, FloatingBar and FloatingToolbar at the bottom.
import { useCallback, type Ref } from "react";

type Edge = "start" | "end";
const PROPERTY = { start: "scrollPaddingBlockStart", end: "scrollPaddingBlockEnd" } as const;

// One record per document and edge, because two bars on one edge (a page and a story beside it, a
// toolbar over a bar) share one scroll padding: it holds the farthest-reaching bar and goes back to
// the page's own value when the last bar leaves, whatever order they mount and unmount in.
const clearance = new WeakMap<Document, Partial<Record<Edge, { original: string; reach: Map<Element, number> }>>>();

function setClearance(el: Element, edge: Edge, reach: number | null) {
  const doc = el.ownerDocument;
  const style = doc.documentElement.style;
  const records = clearance.get(doc) ?? {};
  clearance.set(doc, records);
  const entry = (records[edge] ??= { original: style[PROPERTY[edge]], reach: new Map() });
  if (reach) entry.reach.set(el, reach);
  else entry.reach.delete(el);
  if (entry.reach.size === 0) {
    style[PROPERTY[edge]] = entry.original;
    delete records[edge];
  } else {
    style[PROPERTY[edge]] = `${Math.max(...entry.reach.values())}px`;
  }
}

/** Registers the element as a bar over `edge` while `isActive`, and returns the ref to put on it,
 *  merged with the consumer's own. A bar the CSS hides measures zero and stops counting. */
export function useScrollClearance<T extends HTMLElement>(edge: Edge, ref?: Ref<T>, isActive = true) {
  // The registration lives in the ref callback rather than an effect, so it follows the NODE: a
  // replaced or late-attached element is measured, and the one it replaced lets go.
  return useCallback(
    (node: T | null) => {
      // React 19 runs a returned cleanup instead of calling the ref with null, so the consumer's own
      // cleanup (or its null call) is handed back rather than dropped.
      const theirs = typeof ref === "function" ? ref(node) : ref ? ((ref.current = node), undefined) : undefined;
      const view = node?.ownerDocument.defaultView;
      let release = () => {};
      if (node && view && isActive) {
        // A top bar reaches its own height down; a bottom bar reaches from its top edge to the
        // window's bottom, which takes in the margin it floats at. The window is the node's own, so a
        // bar portalled into an iframe measures against that frame.
        const fit = () => {
          const box = node.getBoundingClientRect();
          const reach = !box.height ? 0 : edge === "start" ? node.offsetHeight : Math.ceil(view.innerHeight - box.top);
          setClearance(node, edge, reach);
        };
        fit();
        const watch = new view.ResizeObserver(fit);
        watch.observe(node);
        // A bar can MOVE without resizing: AppShell stacks its `bottomBar` on the tab bar's top edge
        // once it has measured that bar, so the reach read at registration is the unstacked one. The
        // same update grows the room the page keeps for both bars, which resizes the document, so
        // the document's box is the signal that the bar may have moved.
        watch.observe(node.ownerDocument.documentElement);
        view.addEventListener("resize", fit);
        release = () => {
          watch.disconnect();
          view.removeEventListener("resize", fit);
          setClearance(node, edge, null);
        };
      }
      return () => {
        release();
        if (typeof theirs === "function") theirs();
        else if (typeof ref === "function") ref(null);
        else if (ref) ref.current = null;
      };
    },
    [edge, ref, isActive],
  );
}
